class Solution:
    def sortByAbsoluteValue(self, nums):
        cnt = [0] * 101
        for v in nums:
            cnt[abs(v)] += 1
        i = 0
        for a in range(101):
            for _ in range(cnt[a]):
                nums[i] = -a
                i += 1
            for _ in range(cnt[a]):
                nums[i] = a
                i += 1
        return nums

