class Solution {
public:
    vector<int> sortByAbsoluteValue(vector<int>& nums) {
        int cnt[101] = {0};
        for (int v : nums) cnt[abs(v)]++;
        int i = 0;
        for (int a = 0; a <= 100; a++)
            for (int t = 0; t < cnt[a]; t++) nums[i++] = -a;
        for (int a = 0; a <= 100; a++)
            for (int t = 0; t < cnt[a]; t++) nums[i++] = a;
        return nums;
    }
};

